curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for user in data['members']:
        print(user['id'], user['profile'].get('real_name',''), user['profile'].get('title',''), user.get('is_owner',''), user.get('is_admin',''))
else:
    print(data)
"

